code:
def top_k_frequent(nums, k):
    if not nums or k <= 0:
        return []
    freq = {}
    first_idx = {}
    for i, num in enumerate(nums):
        if num not in freq:
            freq[num] = 0
            first_idx[num] = i
        freq[num] += 1
    distinct = sorted(freq.keys(), key=lambda x: (-freq[x], first_idx[x]))
    return distinct[:k]
